/**
 * Build and send gross metadata from obixGrossList.
 *
 * - Reads controller IP and global obixGrossList
 * - Reads job UUID and other context from global config
 * - Flattens all systems/points into a single array
 * - Adds jobUuid / property / deviceId to each point
 *
 * Output:
 *   msg.payload = {
 *     jobUuid:  <from config>,
 *     property: <from config>,
 *     deviceId: <from config>,
 *     points:   [ ...flattened point objects... ]
 *   }
 */

var config   = global.get('config', 'persistent') || global.get('config') || {};
var jobUuid  = config.JOB_UUID || config.jobUuid || null;
var property = config.property || null;
var deviceId = config.deviceId || null;

// Same IP key used when building obixGrossList
var ip = msg.controllerIp || config.host;

var gross = global.get('obixGrossList','persistent') || {};
var host  = gross[ip];

if (!host || !host.systems) {
    node.warn("No obixGrossList.systems found for IP " + ip);
    msg.payload = {
        jobUuid:  jobUuid,
        property: property,
        deviceId: deviceId,
        points:   []
    };
    return msg;
}

var out = [];

// Flatten all systems → points
Object.keys(host.systems).forEach(function (systemName) {
    var points = host.systems[systemName] || [];
    points.forEach(function (p) {
        if (!p) return;

        out.push({
            // Job / context
            jobUuid:    jobUuid,
            property:   p.property || property,

            // Identity
            HASH:  p.HASH || null,
            name:       p.name,
            label:      p.label,        // /out/ URI
            href:       p.href,
            source:     p.source,       // controller IP

            // Classification
            system:     p.system || systemName,
            component:  p.component || null,
            type:       p.type,
            integrationType: p.integrationType,

            // Presentation
            description: p.description,
            unit:        p.unit,        // engineering unit (symbol or raw)
            value:       p.value,       // last known value (may be null)

            // IDs for grouping
            systemId:   p.systemId,
            componentId:p.componentId,

            // Optional extras
            floor:      p.floor || null,
            zon:        p.zon || null,
            rum:        p.rum || null
        });
    });
});

msg.payload = {
    jobUuid:  jobUuid,
    property: property,
    deviceId: deviceId,
    points:   out
};

return msg;
